(()=>{const filters=document.querySelectorAll("[data-blog-filter]"),cards=Array.from(document.querySelectorAll("[data-blog-card]")),moreButton=document.querySelector("[data-blog-more]"),emptyState=document.querySelector("[data-blog-empty]");let activeCategory="all",visibleLimit=9;function renderCards(){const filteredCards="all"===activeCategory?cards:cards.filter(card=>card.dataset.category===activeCategory);cards.forEach(card=>{card.hidden=!0}),filteredCards.slice(0,visibleLimit).forEach(card=>{card.hidden=!1}),emptyState&&(emptyState.hidden=filteredCards.length>0),moreButton&&(moreButton.hidden=filteredCards.length<=visibleLimit)}filters.forEach(button=>{button.addEventListener("click",()=>{activeCategory=button.dataset.blogFilter,visibleLimit=9,filters.forEach(filter=>{const isActive=filter===button;filter.classList.toggle("is-active",isActive),filter.setAttribute("aria-pressed",String(isActive))}),renderCards()})}),moreButton&&moreButton.addEventListener("click",()=>{visibleLimit+=9,renderCards()}),renderCards()})();